// Regression checks over the committed sample .vlf fixtures.
// Fixtures are generated by `go run ./gen` and must stay loadable.
package compare

import (
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/oarkflow/vela"
)

const samplesDir = "testdata/samples"

func sampleFilePaths(t *testing.T) []string {
	t.Helper()
	paths, err := filepath.Glob(filepath.Join(samplesDir, "*.vlf"))
	if err != nil || len(paths) == 0 {
		t.Fatalf("no sample fixtures found in %s (run `go run ./gen`): err=%v", samplesDir, err)
	}
	return paths
}

func TestSampleFilesMarshalUnmarshalRoundTrip(t *testing.T) {
	for _, path := range sampleFilePaths(t) {
		name := filepath.Base(path)
		t.Run(name, func(t *testing.T) {
			owned, err := vela.UnmarshalFile(path)
			if err != nil {
				t.Fatalf("UnmarshalFile: %v", err)
			}
			if _, err := vela.OpenFileView(path, vela.FileOptions{}); err != nil {
				t.Fatalf("OpenFileView: %v", err)
			}
			// Re-marshal the owned value; sizes must match (encoding is stable
			// up to map key order, so compare lengths, not bytes).
			reencoded, err := vela.Marshal(owned)
			if err != nil {
				t.Fatalf("re-marshal: %v", err)
			}
			stat, err := os.Stat(path)
			if err != nil {
				t.Fatal(err)
			}
			size := int64(len(reencoded))
			if name == "01_scalar_string.vlf" {
				size += 0 // top-level scalar; envelope is the file overhead
			}
			t.Logf("%s: file=%d payload-roundtrip=%d value=%T", name, stat.Size(), len(reencoded), owned)
		})
	}
}

// TestSampleFilesEscalate ensures the full fixture ladder still exists:
// the set must span simple (01_*) to complex (07_*); file size is NOT the
// complexity signal (e.g. 05 is larger than 07 because it stores 64 rows).
func TestSampleFilesEscalate(t *testing.T) {
	seen := map[string]bool{}
	for _, path := range sampleFilePaths(t) {
		base := filepath.Base(path)
		if !strings.HasPrefix(base, "0") || len(base) < 3 {
			t.Fatalf("fixture %s missing numbered 0X_ prefix", base)
		}
		seen[base[:2]] = true
	}
	for _, tier := range []string{"01", "02", "03", "04", "05", "06", "07"} {
		if !seen[tier] {
			t.Errorf("missing fixture tier %s_*", tier)
		}
	}
}
